WITH store_monthly AS ( SELECT d.d_year, d.d_month_seq, 'Store' AS sales_channel, ss.ss_store_sk AS channel_id, SUM(ss.ss_net_paid) AS total_net_paid, SUM(ss.ss_ext_discount_amt) AS total_discount, COUNT(*) AS transaction_count, AVG(CAST(d.d_year AS DOUBLE) - c.c_birth_year) AS avg_customer_age FROM store_sales ss INNER JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk INNER JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk GROUP BY d.d_year, d.d_month_seq, ss.ss_store_sk ), web_monthly AS ( SELECT d.d_year, d.d_month_seq, 'Web' AS sales_channel, ws.ws_web_site_sk AS channel_id, SUM(ws.ws_net_paid) AS total_net_paid, SUM(ws.ws_ext_discount_amt) AS total_discount, COUNT(*) AS transaction_count, AVG(CAST(d.d_year AS DOUBLE) - c.c_birth_year) AS avg_customer_age FROM web_sales ws INNER JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk INNER JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk GROUP BY d.d_year, d.d_month_seq, ws.ws_web_site_sk ), sales_by_month AS ( SELECT * FROM store_monthly UNION ALL SELECT * FROM web_monthly ) SELECT sales_channel, channel_id, d_year, d_month_seq, total_net_paid, total_discount, transaction_count, avg_customer_age, LAG(total_net_paid) OVER (PARTITION BY sales_channel, channel_id ORDER BY d_year, d_month_seq) AS prior_month_net_paid, CASE WHEN LAG(total_net_paid) OVER (PARTITION BY sales_channel, channel_id ORDER BY d_year, d_month_seq) IS NULL THEN NULL WHEN LAG(total_net_paid) OVER (PARTITION BY sales_channel, channel_id ORDER BY d_year, d_month_seq) = 0 THEN NULL ELSE (total_net_paid - LAG(total_net_paid) OVER (PARTITION BY sales_channel, channel_id ORDER BY d_year, d_month_seq)) / LAG(total_net_paid) OVER (PARTITION BY sales_channel, channel_id ORDER BY d_year, d_month_seq) * 100 END AS month_over_month_growth_pct, CASE WHEN LAG(total_net_paid) OVER (PARTITION BY sales_channel, channel_id ORDER BY d_year, d_month_seq) IS NULL THEN 'N/A' WHEN (total_net_paid - LAG(total_net_paid) OVER (PARTITION BY sales_channel, channel_id ORDER BY d_year, d_month_seq)) > 0.1 * LAG(total_net_paid) OVER (PARTITION BY sales_channel, channel_id ORDER BY d_year, d_month_seq) THEN 'Significant Increase' ELSE 'Stable/Decrease' END AS growth_flag FROM sales_by_month ORDER BY sales_channel, channel_id, d_year, d_month_seq
